<?php if(!defined('SW_APP')||!SW_PUBLIC){http_response_code(404);exit;}?>
<p class="user-sub">Consulta tus recargas, entradas y salidas de saldo.</p>
<?php if(!$walletAvailable):?><?php pub_message('El historial aún no está disponible. Contacta al administrador.','warning');?><?php else:
    $filter=$_GET['tipo']??'todos';if(!is_string($filter)||!in_array($filter,['todos','in','out'],true))$filter='todos';
    $pageNo=filter_var($_GET['mov_page']??1,FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>1000000]])?:1;
    $where='user_id=?';$params=[(int)$u['id']];if($filter!=='todos'){$where.=' AND direction=?';$params[]=$filter;}
    $count=(int)(one('SELECT COUNT(*) AS n FROM wallet_movements WHERE '.$where,$params)['n']??0);$maxPage=max(1,(int)ceil($count/25));$pageNo=min($pageNo,$maxPage);$offset=($pageNo-1)*25;
    $moves=all('SELECT direction,amount_cents,concept,reference,created_at FROM wallet_movements WHERE '.$where.' ORDER BY id DESC LIMIT 25 OFFSET '.$offset,$params);
    $recharges=all('SELECT id,amount_cents,state,created_at FROM wallet_recharges WHERE user_id=? ORDER BY created_at DESC,id DESC LIMIT 25',[(int)$u['id']]);?>
    <div class="wallet-stats"><div><small>Saldo disponible</small><strong><?=money($walletTotals['balance'])?></strong></div><div><small>Entradas</small><strong class="wallet-in"><?=money($walletTotals['incoming'])?></strong></div><div><small>Salidas</small><strong class="wallet-out"><?=money($walletTotals['outgoing'])?></strong></div></div>
    <section class="wallet-panel"><div class="wallet-panel-head"><h2>Movimientos</h2><a class="pub-btn secondary" href="<?=h(pub_url('account',['tab'=>'recargar']))?>">＋ Añadir dinero</a></div><nav class="wallet-filters" aria-label="Filtrar movimientos"><?php foreach(['todos'=>'Todos','in'=>'Entradas','out'=>'Salidas'] as $k=>$label):?><a <?=$filter===$k?'aria-current="page"':''?> href="<?=h(pub_url('account',['tab'=>'transacciones','tipo'=>$k]))?>"><?=h($label)?></a><?php endforeach;?></nav>
    <?php if(!$moves):?><div class="user-empty">No tienes movimientos <?=($filter==='in'?'de entrada':($filter==='out'?'de salida':'registrados'))?>.</div><?php else:?><div class="user-table"><table><thead><tr><th>Fecha</th><th>Concepto</th><th>Tipo</th><th>Monto</th></tr></thead><tbody><?php foreach($moves as $m):?><tr><td><?=h($m['created_at'])?></td><td><?=h($m['concept'])?><small class="wallet-ref"><?=h($m['reference'])?></small></td><td><?=$m['direction']==='in'?'Entrada':'Salida'?></td><td class="<?=$m['direction']==='in'?'wallet-in':'wallet-out'?>"><?=$m['direction']==='in'?'+':'−'?><?=money($m['amount_cents'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
    <?php if($maxPage>1):?><div class="wallet-pagination"><?php if($pageNo>1):?><a href="<?=h(pub_url('account',['tab'=>'transacciones','tipo'=>$filter,'mov_page'=>$pageNo-1]))?>">← Anterior</a><?php endif;?><small>Página <?=$pageNo?> de <?=$maxPage?></small><?php if($pageNo<$maxPage):?><a href="<?=h(pub_url('account',['tab'=>'transacciones','tipo'=>$filter,'mov_page'=>$pageNo+1]))?>">Siguiente →</a><?php endif;?></div><?php endif;?></section>
    <section class="wallet-panel"><h2>Solicitudes de recarga</h2><p class="user-sub">Últimas 25 solicitudes. Los pagos pendientes o por conciliar no incrementan tu saldo.</p><?php if(!$recharges):?><div class="user-empty">No tienes solicitudes de recarga.</div><?php else:?><div class="user-table"><table><thead><tr><th>Fecha</th><th>Referencia</th><th>Monto</th><th>Estado</th></tr></thead><tbody><?php foreach($recharges as $r):?><tr><td><?=h($r['created_at'])?></td><td><small><?=h($r['id'])?></small></td><td><?=money($r['amount_cents'])?></td><td><?=h(wallet_recharge_status($r['state']))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php endif;?>
